mapper.select:
SELECT d.id, d.prj_id AS prjId, d.mem_id AS memId,
u.name || '(' || u.login || ')' AS memName,
d.title, d.description, d.created_on AS createdOn FROM document d LEFT JOIN users u ON d.mem_id = u.id WHERE d.id = #{id}

mapper.update:
UPDATE document
SET
title = #{title},
description = #{description}
WHERE id = #{id}
